#define pi     3.14159265
#define A 1.7
#define N 12
#define S 0.2
float generator(vec2 uv,float x)
{

    return log(mod((min(length(uv.x),length(uv.y)))*x+length(uv)*(1.-x)-iTime*S,0.2)/0.2)/log(0.2);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    float a=A;
    int n=N;
    vec2 uv = float(n)*fragCoord/iResolution.y-float(n)*vec2(0.5*iResolution.x/iResolution.y,0.5);

    vec2 uv2=fract(uv)-0.5;
    float x=(sin(1.*iTime+sin(floor(uv.x)*0.15+iTime*2.)+sin(floor(uv.y)*0.15+iTime*1.)+1.)/2.);
    uv2=vec2(

        cos(x*pi*a)*uv2.x - sin(x*pi*a)*uv2.y, 
        sin(x*pi*a)*uv2.x + cos(x*pi*a)*uv2.y
    );


    // Time varying pixel color

    vec3 col=vec3(0.35,0.75,0.7)*generator(uv2,x);

    // Output to screen
    fragColor = vec4(col,1.0);
}
